1	import {
2	  openSync,
3	  closeSync,
4	  writeSync,
5	  fsyncSync,
6	  mkdirSync,
7	  readFileSync,
8	  writeFileSync,
9	  truncateSync,
10	  renameSync,
11	  rmSync,
12	  existsSync,
13	  readdirSync,
14	  statSync,
15	} from 'node:fs';
16	import path from 'node:path';
17	import { randomUUID } from 'node:crypto';
18	
19	const LOG_NAME = 'bus.jsonl';
20	const LOG_TMP_NAME = 'bus.log.tmp';
21	const SNAPSHOT_NAME = 'bus.snapshot.json';
22	const SNAPSHOT_TMP_NAME = 'bus.snapshot.tmp';
23	// The log is a chain of segment files: the active `bus.jsonl` plus finalized
24	// `bus.<index>.jsonl` segments. Index order is oldest first; an index is
25	// never reused within the lifetime of a directory.
26	const SEGMENT_RE = /^bus\.(\d+)\.jsonl$/;
27	const segmentName = (index) => `bus.${String(index).padStart(10, '0')}.jsonl`;
28	
29	/**
30	 * Validate that `value` survives a compact JSON.stringify unchanged.
31	 * JSON silently drops undefined / functions and turns non-finite numbers
32	 * into null; the spec rejects those along with BigInt and circular
33	 * references as TypeError.
34	 */
35	function assertJsonSafe(value, stack = new Set()) {
36	  if (typeof value === 'bigint') {
37	    throw new TypeError('record contains a BigInt');
38	  }
39	  if (typeof value === 'function') {
40	    throw new TypeError('record contains a function');
41	  }
42	  if (typeof value === 'undefined') {
43	    throw new TypeError('record contains undefined');
44	  }
45	  if (typeof value === 'number' && !Number.isFinite(value)) {
46	    throw new TypeError('record contains a non-finite number');
47	  }
48	  if (value !== null && typeof value === 'object') {
49	    // Unbox boxed primitives (e.g. new Number(NaN)) before recursing.
50	    if (value instanceof Number || value instanceof String || value instanceof Boolean) {
51	      assertJsonSafe(value.valueOf(), stack);
52	      return;
53	    }
54	    if (stack.has(value)) {
55	      throw new TypeError('record contains a circular reference');
56	    }
57	    stack.add(value);
58	    if (Array.isArray(value)) {
59	      for (const item of value) assertJsonSafe(item, stack);
60	    } else {
61	      for (const key of Object.keys(value)) assertJsonSafe(value[key], stack);
62	    }
63	    stack.delete(value);
64	  }
65	}
66	
67	/**
68	 * Split a jsonl buffer into parsed entries. `durable` is the offset just
69	 * past the final newline; anything beyond it is a torn trailing write.
70	 */
71	function parseLog(raw) {
72	  const entries = [];
73	  let start = 0;
74	  for (let i = 0; i < raw.length; i++) {
75	    if (raw[i] === 0x0a) {
76	      if (i > start) entries.push(JSON.parse(raw.toString('utf8', start, i)));
77	      start = i + 1;
78	    }
79	  }
80	  return { entries, durable: start };
81	}
82	
83	export function createBus({ path: dir, fsync = false, maxBytes } = {}) {
84	  if (typeof dir !== 'string' || dir.length === 0) {
85	    throw new TypeError('createBus: "path" must be a non-empty string');
86	  }
87	  // Omitted (undefined) means unlimited; any given value must be a positive
88	  // integer — zero, negatives, fractions and non-numbers are TypeErrors.
89	  let quota;
90	  if (maxBytes !== undefined) {
91	    if (typeof maxBytes !== 'number' || !Number.isInteger(maxBytes) || maxBytes <= 0) {
92	      throw new TypeError('createBus: "maxBytes" must be a positive integer');
93	    }
94	    quota = maxBytes;
95	  }
96	
97	  const logPath = path.join(dir, LOG_NAME);
98	  const logTmpPath = path.join(dir, LOG_TMP_NAME);
99	  const snapshotPath = path.join(dir, SNAPSHOT_NAME);
100	  const snapshotTmpPath = path.join(dir, SNAPSHOT_TMP_NAME);
101	
102	  let seq = 0; // seq of the last effective message
103	  let bytes = 0;
104	  let published = 0;
105	  let replayed = 0;
106	  // dedupKey -> { id, seq } for effective messages
107	  const dedup = new Map();
108	  // dedupKey -> { promise, resolve, reject } for first publish in flight
109	  const pending = new Map();
110	  // dedupKey -> { promise, resolve, reject } reserved by the first
111	  // in-flight batch carrying that key; lets later singles/batches share
112	  // the batch's first acknowledgement just like `pending` does for singles
113	  const groupPending = new Map();
114	  // consumer name -> position (seq of the last consumed message; 0 = none)
115	  const positions = new Map();
116	  // generation of the newest durable snapshot; 0 = no snapshot yet
117	  let snapshotGen = 0;
118	  // messages folded into the snapshot, served to replay/read after truncation
119	  let baseMessages = [];
120	  // Every message with seq <= horizon has been discarded by truncate().
121	  let horizon = 0;
122	  // Every message with seq <= foldedSeq lives in the snapshot, not the log.
123	  let foldedSeq = 0;
124	  // Index handed to the next finalized segment; never reused within a run.
125	  let nextSegmentIndex = 1;
126	  // Business bytes of the messages still retained (seq > horizon, i.e.
127	  // snapshot survivors plus live-log messages). Unlike the cumulative
128	  // `bytes` stat this shrinks when retention truncation frees messages;
129	  // compaction only reshapes the log and never changes it.
130	  let usageBytes = 0;
131	
132	  // ---- synchronous recovery so stats() is correct the moment createBus returns
133	  mkdirSync(dir, { recursive: true });
134	
135	  // A leftover tmp file is a snapshot that crashed mid-write. The pre-compact
136	  // log is still intact, so the half snapshot carries no state: drop it.
137	  rmSync(snapshotTmpPath, { force: true });
138	  // Likewise a log tmp left behind when compact crashed before the rename:
139	  // the live log (if any) is still the source of truth.
140	  rmSync(logTmpPath, { force: true });
141	
142	  if (existsSync(snapshotPath)) {
143	    const snap = JSON.parse(readFileSync(snapshotPath, 'utf8'));
144	    snapshotGen = snap.gen;
145	    seq = snap.seq;
146	    bytes = snap.bytes;
147	    published = snap.published;
148	    replayed = snap.replayed;
149	    // Snapshots written before truncation existed carry no horizon.
150	    horizon = snap.horizon ?? 0;
151	    foldedSeq = snap.seq;
152	    for (const [key, value] of snap.dedup) dedup.set(key, value);
153	    for (const [name, pos] of Object.entries(snap.positions)) positions.set(name, pos);
154	    baseMessages = snap.messages;
155	  }
156	
157	  const applyEntry = (entry) => {
158	    if (entry.t === 'm') {
159	      // At/below the horizon the message was discarded by truncation; only
160	      // its cumulative counters (carried by the marker) survive.
161	      if (entry.seq <= horizon) return;
162	      seq = entry.seq;
163	      bytes += entry.bytes;
164	      published += 1;
165	      if (typeof entry.d === 'string') {
166	        dedup.set(entry.d, { id: entry.id, seq: entry.seq });
167	      }
168	    } else if (entry.t === 's') {
169	      replayed += entry.n;
170	    } else if (entry.t === 'p') {
171	      positions.set(entry.name, entry.pos);
172	    }
173	  };
174	
175	  // A truncate marker is an absolute checkpoint: the cumulative counters,
176	  // positions and dedup table it carries replace whatever earlier segments
177	  // established, so recovery can start from the newest marker and ignore
178	  // everything before it.
179	  const applyMarker = (entry) => {
180	    seq = entry.seq;
181	    bytes = entry.bytes;
182	    published = entry.published;
183	    replayed = entry.replayed;
184	    horizon = entry.horizon;
185	    positions.clear();
186	    for (const [name, pos] of Object.entries(entry.positions)) positions.set(name, pos);
187	    dedup.clear();
188	    for (const [key, value] of entry.dedup) dedup.set(key, value);
189	  };
190	
191	  const markerLine = (gen) => JSON.stringify({ t: 'c', gen }) + '\n';
192	
193	  // Replay complete log lines and apply only the committed prefix.
194	  // A batch is bracketed by {t:'b',id} .. entries .. {t:'bk',id}: a begin
195	  // without its matching commit (crash mid-write, or overtaken by a newer
196	  // begin) is severed wholesale and none of its entries take effect.
197	  // Returns the byte offset just past the last committed line, so both a
198	  // torn trailing write and an uncommitted batch tail can be truncated.
199	  const recoverLog = (raw) => {
200	    let lineStart = 0;
201	    let committedEnd = 0;
202	    let group = null;
203	    for (let i = 0; i < raw.length; i++) {
204	      if (raw[i] !== 0x0a) continue;
205	      const entry = i > lineStart ? JSON.parse(raw.toString('utf8', lineStart, i)) : null;
206	      if (group !== null) {
207	        if (entry && entry.t === 'bk' && entry.id === group.id) {
208	          for (const e of group.entries) applyEntry(e);
209	          group = null;
210	          committedEnd = i + 1;
211	        } else if (entry && entry.t === 'b') {
212	          // The previous group never committed; start tracking the new one.
213	          group = { id: entry.id, entries: [] };
214	        } else if (entry) {
215	          group.entries.push(entry);
216	        }
217	      } else if (entry && entry.t === 'b') {
218	        group = { id: entry.id, entries: [] };
219	      } else {
220	        if (entry) {
221	          if (entry.t === 't') applyMarker(entry);
222	          else applyEntry(entry);
223	        }
224	        committedEnd = i + 1;
225	      }
226	      lineStart = i + 1;
227	    }
228	    return committedEnd;
229	  };
230	
231	  // Finalized segments present in the directory, oldest first.
232	  const listSegments = () => {
233	    const out = [];
234	    for (const name of readdirSync(dir)) {
235	      const match = SEGMENT_RE.exec(name);
236	      if (match) out.push({ index: Number(match[1]), path: path.join(dir, name) });
237	    }
238	    out.sort((a, b) => a.index - b.index);
239	    return out;
240	  };
241	
242	  // First complete line of a log file, or null when there is none.
243	  const firstEntry = (filePath) => {
244	    const raw = readFileSync(filePath);
245	    const nl = raw.indexOf(0x0a);
246	    if (nl <= 0) return null;
247	    try {
248	      return JSON.parse(raw.toString('utf8', 0, nl));
249	    } catch {
250	      return null;
251	    }
252	  };
253	
254	  // Highest message seq in a segment file; null when it carries no messages.
255	  const segmentMaxSeq = (filePath) => {
256	    const { entries } = parseLog(readFileSync(filePath));
257	    let max = null;
258	    for (const entry of entries) {
259	      if (entry.t === 'm' && (max === null || entry.seq > max)) max = entry.seq;
260	    }
261	    return max;
262	  };
263	
264	  const segments = listSegments();
265	  for (const seg of segments) {
266	    if (seg.index >= nextSegmentIndex) nextSegmentIndex = seg.index + 1;
267	  }
268	  // The ordered log is every finalized segment (oldest first) followed by
269	  // the active log file.
270	  const ordered = segments.map((seg) => seg.path);
271	  if (existsSync(logPath)) ordered.push(logPath);
272	
273	  // The newest anchor — a segment whose first line is a compact ('c') or
274	  // truncate ('t') marker for the current snapshot generation — starts the
275	  // live suffix of the log. Everything before it is folded into the snapshot
276	  // or checkpointed into that marker.
277	  let startAt = -1;
278	  for (let i = 0; i < ordered.length; i++) {
279	    const first = firstEntry(ordered[i]);
280	    if (first && (first.t === 'c' || first.t === 't') && first.gen === snapshotGen) {
281	      startAt = i;
282	    }
283	  }
284	
285	  if (snapshotGen > 0 && startAt < 0) {
286	    // Crash between the snapshot rename and the log reset: every byte still
287	    // on disk is already folded into the snapshot. Reset to a marker-led log
288	    // so the state is unambiguous from here on.
289	    for (const seg of segments) rmSync(seg.path, { force: true });
290	    writeFileSync(logPath, markerLine(snapshotGen));
291	  } else {
292	    // Replay the live suffix; a torn tail or uncommitted batch is severed.
293	    for (let i = Math.max(startAt, 0); i < ordered.length; i++) {
294	      const raw = readFileSync(ordered[i]);
295	      const committedEnd = recoverLog(raw);
296	      if (committedEnd < raw.length) truncateSync(ordered[i], committedEnd);
297	    }
298	    // Reconcile leftovers of an interrupted truncate/compact: finalized
299	    // segments before the anchor whose content is folded into the snapshot
300	    // or at/below the truncation horizon can go. Segments a consumer still
301	    // needs (above the horizon) stay untouched.
302	    for (let i = 0; i < startAt; i++) {
303	      const max = segmentMaxSeq(ordered[i]);
304	      if (max === null || max <= foldedSeq || max <= horizon) {
305	        rmSync(ordered[i], { force: true });
306	      }
307	    }
308	  }
309	
310	  // Recompute retained bytes from the surviving messages after recovery:
311	  // snapshot survivors plus messages in finalized segments and the active
312	  // log above both the horizon and the folded floor. Torn tails and
313	  // uncommitted batches were severed above, so their bytes never count —
314	  // usage always matches the messages actually alive.
315	  for (const m of baseMessages) {
316	    if (m.seq > horizon) usageBytes += Buffer.byteLength(JSON.stringify(m.record), 'utf8');
317	  }
318	  {
319	    const logFloor = Math.max(horizon, foldedSeq);
320	    const sumFile = (filePath) => {
321	      if (!existsSync(filePath)) return;
322	      const { entries } = parseLog(readFileSync(filePath));
323	      for (const entry of entries) {
324	        if (entry.t === 'm' && entry.seq > logFloor) usageBytes += entry.bytes;
325	      }
326	    };
327	    for (const seg of listSegments()) sumFile(seg.path);
328	    sumFile(logPath);
329	  }
330	
331	  // Reassigned by compact()/truncate() when they swap the active log.
332	  let fd = openSync(logPath, 'a');
333	
334	  let chain = Promise.resolve();
335	  let closed = false;
336	  // A failed append may leave a torn line; stop appending so later writes
337	  // cannot glue themselves onto it. The torn tail is truncated on reopen.
338	  let broken = false;
339	
340	  // All disk mutation by publish/replay/compact/truncate happens inside this
341	  // serial chain; writeSync keeps each append atomic with respect to the
342	  // event loop while still returning a Promise to callers.
343	  const enqueue = (job) => {
344	    const run = chain.then(job);
345	    // A failed job must not stall every later operation.
346	    chain = run.then(
347	      () => {},
348	      () => {},
349	    );
350	    return run;
351	  };
352	
353	  const writeLine = (entry) => {
354	    writeSync(fd, Buffer.from(JSON.stringify(entry) + '\n', 'utf8'));
355	    if (fsync) fsyncSync(fd);
356	  };
357	
358	  // Position writes are synchronous (register/advance/read are synchronous
359	  // methods) and order-independent against 'm'/'s' entries, so they append
360	  // directly rather than through the chain.
361	  const persistPosition = (name, pos) => {
362	    try {
363	      writeLine({ t: 'p', name, pos });
364	    } catch (err) {
365	      broken = true;
366	      throw err;
367	    }
368	  };
369	
370	  const assertOpen = () => {
371	    if (closed || broken) {
372	      throw new Error('bus is closed');
373	    }
374	  };
375	
376	  const assertName = (name) => {
377	    if (typeof name !== 'string' || name.length === 0) {
378	      throw new TypeError('consumer name must be a non-empty string');
379	    }
380	  };
381	
382	  // Messages with seq > pos that survived truncation, snapshot first then
383	  // live segments, ascending. A position below the truncation horizon simply
384	  // starts at the earliest surviving message: the gap is already truncated.
385	  const messagesAfter = (pos) => {
386	    const floor = Math.max(pos, horizon);
387	    const out = [];
388	    for (const m of baseMessages) {
389	      if (m.seq > floor) {
390	        // Snapshot messages are shared in-memory objects; hand out a copy so
391	        // callers cannot mutate replay/read results for later calls.
392	        out.push({ seq: m.seq, id: m.id, record: structuredClone(m.record) });
393	      }
394	    }
395	    // Log entries at/below foldedSeq are covered by the snapshot (a leftover
396	    // segment from an interrupted compaction can still be on disk).
397	    const logFloor = Math.max(floor, foldedSeq);
398	    const collect = (filePath) => {
399	      const { entries } = parseLog(readFileSync(filePath));
400	      for (const entry of entries) {
401	        if (entry.t === 'm' && entry.seq > logFloor) {
402	          out.push({ seq: entry.seq, id: entry.id, record: entry.record });
403	        }
404	      }
405	    };
406	    for (const seg of listSegments()) collect(seg.path);
407	    collect(logPath);
408	    return out;
409	  };
410	
411	  const bus = {
412	    publish(record) {
413	      if (closed) {
414	        return Promise.reject(new Error('bus is closed'));
415	      }
416	      if (record === null || typeof record !== 'object' || Array.isArray(record)) {
417	        return Promise.reject(new TypeError('publish: record must be a JSON object'));
418	      }
419	      const dedupKey = record.dedupKey;
420	      if (dedupKey !== undefined && typeof dedupKey !== 'string') {
421	        return Promise.reject(new TypeError('publish: dedupKey must be a string'));
422	      }
423	      try {
424	        assertJsonSafe(record);
425	      } catch (err) {
426	        return Promise.reject(err);
427	      }
428	      const size = Buffer.byteLength(JSON.stringify(record), 'utf8');
429	
430	      // Duplicate of an effective message (possibly recovered from disk).
431	      if (dedupKey !== undefined) {
432	        const first = dedup.get(dedupKey);
433	        if (first) {
434	          return Promise.resolve({ id: first.id, seq: first.seq });
435	        }
436	        const inflight = pending.get(dedupKey);
437	        if (inflight) {
438	          return inflight.promise;
439	        }
440	        const inflightGroup = groupPending.get(dedupKey);
441	        if (inflightGroup) {
442	          return inflightGroup.promise;
443	        }
444	      }
445	
446	      // Reserve in-flight dedup at call time so concurrent resends of the
447	      // same order share the first result; FIFO enqueue assigns seq in
448	      // invocation order.
449	      let resolveResult;
450	      let rejectResult;
451	      const promise = new Promise((resolve, reject) => {
452	        resolveResult = resolve;
453	        rejectResult = reject;
454	      });
455	      if (dedupKey !== undefined) {
456	        pending.set(dedupKey, { promise, resolve: resolveResult, reject: rejectResult });
457	      }
458	
459	      enqueue(() => {
460	        if (closed || broken) {
461	          throw new Error('bus is closed');
462	        }
463	        // Quota is checked inside the serial job, so a truncate queued
464	        // earlier releases its bytes before this publish is judged. An
465	        // exact fit succeeds; one byte over (or a single oversized record)
466	        // rejects before anything is written — state stays untouched.
467	        if (quota !== undefined && usageBytes + size > quota) {
468	          throw new RangeError('publish: retained bytes would exceed maxBytes');
469	        }
470	        const mySeq = seq + 1;
471	        const id = randomUUID();
472	        const entry = { t: 'm', seq: mySeq, id, bytes: size, record };
473	        if (dedupKey !== undefined) entry.d = dedupKey;
474	        try {
475	          // Durable before acknowledgement: state changes only after the
476	          // write (and optional fsync) succeeds.
477	          writeLine(entry);
478	        } catch (err) {
479	          broken = true;
480	          throw err;
481	        }
482	        seq = mySeq;
483	        bytes += size;
484	        usageBytes += size;
485	        published += 1;
486	        if (dedupKey !== undefined) {
487	          dedup.set(dedupKey, { id, seq: mySeq });
488	          pending.delete(dedupKey);
489	          resolveResult({ id, seq: mySeq });
490	        }
491	        return { id, seq: mySeq };
492	      }).then(
493	        (ack) => {
494	          if (dedupKey === undefined) resolveResult(ack);
495	        },
496	        (err) => {
497	          if (dedupKey !== undefined) pending.delete(dedupKey);
498	          rejectResult(err);
499	        },
500	      );
501	
502	      return promise;
503	    },
504	
505	    publishBatch(records) {
506	      // Spec: a non-array argument is always a synchronous TypeError.
507	      if (!Array.isArray(records)) {
508	        throw new TypeError('publishBatch: records must be an array');
509	      }
510	      if (closed) {
511	        return Promise.reject(new Error('bus is closed'));
512	      }
513	
514	      // Validate and serialize every record up front. Any single bad shape
515	      // (or value JSON cannot carry) rejects the whole group before the
516	      // serial chain is touched: seq/bytes/published/dedup/positions stay
517	      // exactly as they were.
518	      const prepared = [];
519	      try {
520	        for (const record of records) {
521	          if (record === null || typeof record !== 'object' || Array.isArray(record)) {
522	            throw new TypeError('publishBatch: record must be a JSON object');
523	          }
524	          const dedupKey = record.dedupKey;
525	          if (dedupKey !== undefined && typeof dedupKey !== 'string') {
526	            throw new TypeError('publishBatch: dedupKey must be a string');
527	          }
528	          assertJsonSafe(record);
529	          // Serialize exactly once per record: the byte count used for
530	          // stats and the bytes actually appended must be the same string.
531	          const recordJson = JSON.stringify(record);
532	          prepared.push({
533	            dedupKey,
534	            recordJson,
535	            size: Buffer.byteLength(recordJson, 'utf8'),
536	          });
537	        }
538	      } catch (err) {
539	        return Promise.reject(err);
540	      }
541	      if (prepared.length === 0) {
542	        return Promise.resolve([]);
543	      }
544	
545	      // Reserve the group's first-occurrence keys at call time, mirroring
546	      // publish()'s `pending`: a concurrent single or batch carrying the
547	      // same key shares this group's first acknowledgement. Keys already in
548	      // history or reserved by an earlier in-flight op are left alone.
549	      const reservations = new Map();
550	      for (const item of prepared) {
551	        const key = item.dedupKey;
552	        if (key === undefined) continue;
553	        if (dedup.has(key) || pending.has(key) || groupPending.has(key)) continue;
554	        if (reservations.has(key)) continue;
555	        let resolveResult;
556	        let rejectResult;
557	        const promise = new Promise((resolve, reject) => {
558	          resolveResult = resolve;
559	          rejectResult = reject;
560	        });
561	        // This promise is a coordination primitive: callers that race the
562	        // reservation attach their own branch (publish returns it). A group
563	        // with no such racer would otherwise leave the rejection unhandled
564	        // when the bus closes before the job runs. The noop branch only
565	        // handles the event for the process; racers still observe it.
566	        promise.catch(() => {});
567	        const reservation = { promise, resolve: resolveResult, reject: rejectResult };
568	        reservations.set(key, reservation);
569	        groupPending.set(key, reservation);
570	      }
571	
572	      return enqueue(() => {
573	        if (closed || broken) {
574	          throw new Error('bus is closed');
575	        }
576	
577	        // Resolve the whole plan against durable state inside the serial
578	        // job, so groups queued behind earlier publishes/batches observe
579	        // their committed dedup keys.
580	        const gid = randomUUID();
581	        let nextSeq = seq;
582	        let effectiveBytes = 0;
583	        const owned = new Map(); // key -> first acknowledgement within group
584	        const keyAcks = new Map(); // every dedup key's resolved acknowledgement
585	        const planned = prepared.map((item) => {
586	          const key = item.dedupKey;
587	          if (key !== undefined) {
588	            const hist = dedup.get(key);
589	            if (hist) {
590	              const reuse = { id: hist.id, seq: hist.seq };
591	              keyAcks.set(key, reuse);
592	              return { reuse };
593	            }
594	            const earlier = owned.get(key);
595	            if (earlier) {
596	              return { reuse: earlier };
597	            }
598	          }
599	          nextSeq += 1;
600	          const id = randomUUID();
601	          const ack = { id, seq: nextSeq };
602	          if (key !== undefined) {
603	            owned.set(key, ack);
604	            keyAcks.set(key, ack);
605	          }
606	          // Splice the already-serialized record into the line so the
607	          // persisted bytes are exactly what `size` counted.
608	          let line = `{"t":"m","seq":${nextSeq},"id":${JSON.stringify(id)},"bytes":${item.size}`;
609	          if (key !== undefined) line += `,"d":${JSON.stringify(key)}`;
610	          line += `,"record":${item.recordJson}}\n`;
611	          effectiveBytes += item.size;
612	          return { effective: { ack, line, size: item.size, key } };
613	        });
614	
615	        // Shape validation happened at call time; quota is judged for the
616	        // whole group here, against committed state and counting only the
617	        // first occurrence of each key. One byte over rejects the entire
618	        // group before the bracket is opened — no seq, stat or file change.
619	        if (quota !== undefined && usageBytes + effectiveBytes > quota) {
620	          throw new RangeError('publishBatch: retained bytes would exceed maxBytes');
621	        }
622	
623	        // One begin-bracket, the group's new messages, one commit-bracket.
624	        // Recovery applies the bracketed entries only when the commit is
625	        // present, so a crash leaves no trace of the group.
626	        const buffers = [Buffer.from(JSON.stringify({ t: 'b', id: gid }) + '\n', 'utf8')];
627	        for (const part of planned) {
628	          if (part.effective) {
629	            buffers.push(Buffer.from(part.effective.line, 'utf8'));
630	          }
631	        }
632	        buffers.push(Buffer.from(JSON.stringify({ t: 'bk', id: gid }) + '\n', 'utf8'));
633	
634	        try {
635	          // Coalesce in small chunks (bounds peak memory for huge groups)
636	          // and loop over partial writes. Single-buffer writeSync is used
637	          // rather than writev so the append behaves identically on Windows.
638	          // Everything here is synchronous inside this job, so no position
639	          // write can interleave. The begin/commit brackets keep the group
640	          // atomic across a crash even if a partial write occurs.
641	          const CHUNK = 256;
642	          for (let i = 0; i < buffers.length; i += CHUNK) {
643	            const chunk = Buffer.concat(buffers.slice(i, i + CHUNK));
644	            let off = 0;
645	            while (off < chunk.length) {
646	              const written = writeSync(fd, chunk, off, chunk.length - off);
647	              if (!Number.isInteger(written) || written <= 0) {
648	                throw new Error('publishBatch: write made no progress, group is not durable');
649	              }
650	              off += written;
651	            }
652	          }
653	          if (fsync) fsyncSync(fd);
654	        } catch (err) {
655	          // Nothing is applied in memory; the uncommitted bracket is
656	          // severed on reopen. Stop the bus so later writes cannot glue
657	          // themselves onto the partial group. Reservations are reclaimed
658	          // by the outer catch below.
659	          broken = true;
660	          throw err;
661	        }
662	
663	        // Durable first, state after.
664	        for (const part of planned) {
665	          if (!part.effective) continue;
666	          const { ack, size, key } = part.effective;
667	          seq = ack.seq;
668	          bytes += size;
669	          usageBytes += size;
670	          published += 1;
671	          if (key !== undefined) dedup.set(key, { id: ack.id, seq: ack.seq });
672	        }
673	
674	        const acks = planned.map((part) =>
675	          part.reuse ? { id: part.reuse.id, seq: part.reuse.seq } : { id: part.effective.ack.id, seq: part.effective.ack.seq },
676	        );
677	        for (const [key, reservation] of reservations) {
678	          groupPending.delete(key);
679	          reservation.resolve(keyAcks.get(key));
680	        }
681	        return acks;
682	      }).catch((err) => {
683	        // Covers write failure inside the job and rejection before the job
684	        // body (closed/broken bus): release any reservation still pointing
685	        // at this failed group.
686	        for (const [key, reservation] of reservations) {
687	          if (groupPending.get(key) === reservation) groupPending.delete(key);
688	          reservation.reject(err);
689	        }
690	        throw err;
691	      });
692	    },
693	
694	    replay(from = 0) {
695	      if (closed) {
696	        return Promise.reject(new Error('bus is closed'));
697	      }
698	      if (typeof from !== 'number' || !Number.isInteger(from) || from < 0) {
699	        return Promise.reject(new RangeError('replay: from must be a non-negative integer'));
700	      }
701	
702	      return enqueue(() => {
703	        if (closed || broken) {
704	          throw new Error('bus is closed');
705	        }
706	        // replay(from) is inclusive of from; messagesAfter takes an
707	        // exclusive lower bound.
708	        const out = messagesAfter(from - 1);
709	        const n = out.length;
710	        if (n > 0) {
711	          try {
712	            writeLine({ t: 's', n });
713	          } catch (err) {
714	            broken = true;
715	            throw err;
716	          }
717	          replayed += n;
718	        }
719	        return out;
720	      });
721	    },
722	
723	    register(name) {
724	      assertOpen();
725	      assertName(name);
726	      const current = positions.get(name);
727	      // Re-registering an existing name must not reset its position.
728	      if (current !== undefined) {
729	        return current;
730	      }
731	      persistPosition(name, 0);
732	      positions.set(name, 0);
733	      return 0;
734	    },
735	
736	    advance(name, to) {
737	      assertOpen();
738	      assertName(name);
739	      if (typeof to !== 'number' || !Number.isInteger(to) || to < 0) {
740	        throw new RangeError('advance: position must be a non-negative integer');
741	      }
742	      const current = positions.get(name);
743	      if (current !== undefined) {
744	        if (to < current) {
745	          throw new RangeError('advance: position cannot move backwards');
746	        }
747	        if (to === current) {
748	          return current;
749	        }
750	      }
751	      // An unknown name is auto-registered, same as register() first.
752	      persistPosition(name, to);
753	      positions.set(name, to);
754	      return to;
755	    },
756	
757	    read(name) {
758	      assertOpen();
759	      assertName(name);
760	      let pos = positions.get(name);
761	      if (pos === undefined) {
762	        pos = 0;
763	        persistPosition(name, pos);
764	        positions.set(name, pos);
765	      }
