    return fn();
  } finally {
    try {
      rmSync(lockPath, { recursive: true, force: true });
    } catch {
      // Unlock is best-effort; the stale-lock path above reclaims it.
    }
  }
};

// A lease tmp from a process that crashed during the (tiny) atomic write
// carries no state; drop leftovers before deciding ownership.
try {
