async function freshDir() {
  const dir = path.join(tmpdir(), `replay-bus-mw-${Math.random().toString(36).slice(2)}`);
  await mkdir(dir, { recursive: true });
  dirs.push(dir);
  return dir;
}

afterEach(async () => {
