import { spawn } from 'node:child_process';
import { mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
const dir = mkdtempSync(path.join(tmpdir(),'stress-'));
const WORKER=new URL('./helpers/worker.mjs', 'file://'+process.cwd()+'/').pathname;
function mk(env={}){
 const c=spawn(process.execPath,[WORKER],{stdio:['pipe','pipe','inherit'],env:{...process.env,...env,BUS_DIR:dir}});
 let n=1; const pend=new Map(); let buf='';
 c.stdout.setEncoding('utf8'); c.stdout.on('data',d=>{buf+=d;let i;while((i=buf.indexOf('\n'))>=0){const l=buf.slice(0,i);buf=buf.slice(i+1);if(!l)continue;const m=JSON.parse(l);pend.get(m.id)?.(m);pend.delete(m.id);}});
 const call=(op,p={})=>new Promise((res,rej)=>{const id=n++;pend.set(id,m=>m.error?rej(Object.assign(new Error(m.message),{name:m.error})):res(m.value));c.stdin.write(JSON.stringify({id,op,...p})+'\n');});
 return {call,kill:()=>c.kill()};
}
const procs=[mk(),mk(),mk()];
const jobs=[];
for(let r=0;r<3;r++)for(let i=0;i<50;i++){const p=procs[i%3];jobs.push(p.call('publish',{record:{r,i,big:'x'.repeat((i%7)*50)}}));if(i%9===0)jobs.push(p.call('publishBatch',{records:[{batch:i},{batch:i+0.5,dedupKey:'d'+i}]}));if(i%13===0)jobs.push(procs[(i+1)%3].call('compact'));if(i%17===0)jobs.push(procs[(i+2)%3].call('truncate',{before:i}));}
const acks=await Promise.all(jobs);
const pubs=acks.filter(a=>a&&!Array.isArray(a)&&typeof a.seq==='number');
