console.log('replay',got.length,'seqmatch',got.length&&got[got.length-1].seq===got.length?false: 'suffix-ok', 'published', bus.stats().published);
let ok=true;for(let k=1;k<got.length;k++)if(got[k].seq!==got[k-1].seq+1)ok=false;
console.log('replay contiguous suffix',ok,'lastSeq',got[got.length-1]?.seq,'statsSeq',bus.stats().seq);
await bus.close();
"

