import { spawn } from 'node:child_process';
import { mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const WORKER = path.join(HERE, 'helpers', 'worker.mjs');

const hardTimer = setTimeout(() => {
  console.error('STRESS TIMEOUT');
  process.exit(1);
}, 45000);

function mk(dir, env = {}) {
  const c = spawn(process.execPath, [WORKER], {
    stdio: ['pipe', 'pipe', 'inherit'],
    env: { ...process.env, ...env, BUS_DIR: dir },
  });
  let n = 1;
  const pend = new Map();
  let buf = '';
  c.stdout.setEncoding('utf8');
  c.stdout.on('data', (d) => {
    buf += d;
    let i;
    while ((i = buf.indexOf('\n')) >= 0) {
      const l = buf.slice(0, i);
      buf = buf.slice(i + 1);
      if (!l) continue;
      const m = JSON.parse(l);
      const s = pend.get(m.id);
      if (s) {
        pend.delete(m.id);
        s(m);
      }
    }
  });
  const call = (op, p = {}) =>
    new Promise((res, rej) => {
      const id = n++;
      pend.set(id, (m) =>
        m.error ? rej(Object.assign(new Error(m.message), { name: m.error })) : res(m.value),
      );
      c.stdin.write(JSON.stringify({ id, op, ...p }) + '\n');
    });
  return { call, kill: () => c.kill() };
}

const dir = mkdtempSync(path.join(tmpdir(), 'stress-'));
const procs = [mk(dir), mk(dir), mk(dir)];
const jobs = [];
for (let r = 0; r < 3; r++) {
  for (let i = 0; i < 40; i++) {
    const p = procs[i % 3];
    jobs.push(p.call('publish', { record: { r, i, big: 'x'.repeat((i % 7) * 40) } }));
    if (i % 9 === 0)
      jobs.push(
        p.call('publishBatch', { records: [{ batch: i }, { batch: i + 0.5, dedupKey: 'd' + i }] }),
      );
    if (i % 11 === 0) jobs.push(procs[(i + 1) % 3].call('compact'));
    if (i % 13 === 0) jobs.push(procs[(i + 2) % 3].call('truncate', { before: i }));
  }
}
const acks = await Promise.all(jobs);
const pubs = acks.filter((a) => a && !Array.isArray(a) && typeof a.seq === 'number');
const seqs = pubs.map((a) => a.seq).sort((x, y) => x - y);
let gaps = 0;
for (let i = 1; i < seqs.length; i++) if (seqs[i] !== seqs[i - 1] + 1) gaps++;
console.log('effective', pubs.length, 'gaps', gaps, 'min', seqs[0], 'max', seqs.at(-1));
for (const p of procs) await p.call('close');

const { createBus } = await import(path.join(HERE, 'src', 'index.js'));
const bus = createBus({ path: dir });
const got = await bus.replay(0);
let ok = true;
for (let k = 1; k < got.length; k++) if (got[k].seq !== got[k - 1].seq + 1) ok = false;
console.log(
  'replay',
  got.length,
  'contiguousSuffix',
  ok,
  'published',
  bus.stats().published,
  'seq',
  bus.stats().seq,
);
await bus.close();
clearTimeout(hardTimer);

