import { mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const WORKER = path.join(HERE, 'helpers', 'worker.mjs');
const dir = mkdtempSync(path.join(tmpdir(), 'life-'));

function mk() {
  const c = spawn(process.execPath, [WORKER], {
    stdio: ['pipe', 'pipe', 'inherit'],
    env: { ...process.env, BUS_DIR: dir },
  });
  let n = 1;
  const pend = new Map();
  let buf = '';
  c.stdout.setEncoding('utf8');
  c.stdout.on('data', (d) => {
    buf += d;
    let i;
    while ((i = buf.indexOf('\n')) >= 0) {
      const l = buf.slice(0, i);
      buf = buf.slice(i + 1);
      if (!l) continue;
      const m = JSON.parse(l);
      const s = pend.get(m.id);
      if (s) {
        pend.delete(m.id);
        s(m);
      }
    }
  });
  const call = (op, p = {}) =>
    new Promise((res, rej) => {
      const id = n++;
      pend.set(id, (m) => (m.error ? rej(new Error(m.message)) : res(m.value)));
      c.stdin.write(JSON.stringify({ id, op, ...p }) + '\n');
    });
  return { call, kill: () => c.kill() };
}

